mapper.select:
/* 뉴스 목록 조회 */ SELECT N.NEWS_SN , N.NEWS_CLSF_CD , N.NEWS_SRC_CD , C.COM_CD_NM AS NEWS_SRC_CD_NM , N.SRC_PRESS_NM , N.NEWS_TTL , LEFT(N.NEWS_CN, 200) AS NEWS_CN , N.PBLCN_DT , N.THMB_URL_PATH , N.ATCH_FILE_SN FROM NEWS N LEFT JOIN COM_CD C ON C.COM_CD = N.NEWS_SRC_CD AND C.COM_CD_PRNT_SN IS NOT NULL WHERE N.USE_YN = 'Y'
AND N.NEWS_CLSF_CD = #{newsClsfCd}
AND ( N.NEWS_TTL LIKE CONCAT('%', #{keyword}, '%') OR N.NEWS_CN LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY N.PBLCN_DT DESC, N.NEWS_SN DESC

/* 이미 저장된 원문 경로 조회 */
SELECT N.ORGTXT_PATH
  FROM NEWS N
 WHERE N.ORGTXT_PATH IN

    #{orgtxtPath}

/* 중복 판정용 최근 기사 조회 */
SELECT N.NEWS_TTL
     , N.NEWS_CN
  FROM NEWS N
 WHERE N.PBLCN_DT >= #{since}

/* 관리자 뉴스 목록 조회 : 숨긴 기사 포함 */ SELECT N.NEWS_SN , N.ATCH_FILE_SN , N.NEWS_CLSF_CD , N.NEWS_SRC_CD , C.COM_CD_NM AS NEWS_SRC_CD_NM , N.NEWS_TTL , N.NEWS_CN , N.SRC_PRESS_NM , N.ORGTXT_PATH , N.PBLCN_DT , CASE WHEN N.USE_YN = 'Y' THEN TRUE ELSE FALSE END AS USE_YN , N.REG_DT , N.MDFCN_DT , N.THMB_URL_PATH FROM NEWS N LEFT JOIN COM_CD C ON C.COM_CD = N.NEWS_SRC_CD AND C.COM_CD_PRNT_SN IS NOT NULL
AND N.NEWS_SRC_CD = #{newsSrcCd}
AND N.NEWS_CLSF_CD = #{newsClsfCd}
ORDER BY N.REG_DT DESC, N.NEWS_SN DESC

mapper.insert:
/* 관리자 뉴스 등록 : 원문 경로 없음 */
INSERT INTO NEWS (ATCH_FILE_SN, NEWS_CLSF_CD, NEWS_SRC_CD, NEWS_TTL, NEWS_CN, PBLCN_DT, USE_YN)
VALUES (#{atchFileSn}, #{newsClsfCd}, #{newsSrcCd}, #{newsTtl}, #{newsCn}, #{pblcnDt}, #{useYn})

mapper.update:
/* 관리자 뉴스 수정 : 보낸 칸만 */ UPDATE NEWS
ATCH_FILE_SN = #{atchFileSn}, NEWS_CLSF_CD = #{newsClsfCd}, NEWS_TTL = #{newsTtl}, NEWS_CN = #{newsCn}, USE_YN = #{useYn},
WHERE NEWS_SN = #{newsSn}

mapper.select:
/* 같은 카테고리 키워드 중복 확인 : 쉼표로 이어진 지난 행도 본다, 콜레이션이 대소문자 무시 */
SELECT EXISTS (
    SELECT 1
      FROM KWRD_DICT K
     WHERE K.DICT_USG_CD = 'AIMC0039'
       AND K.MPNG_CD = #{mpngCd}
       AND K.USE_YN = 'Y'
       AND K.DEL_YN = 'N'
       AND FIND_IN_SET(#{kwrdCn}, REPLACE(K.KWRD_CN, ', ', ',')) > 0
)

mapper.insert:
/* 분류 키워드 등록 : 항목명은 카테고리 이름 */
INSERT INTO KWRD_DICT (DICT_USG_CD, KWRD_CLSF_NM, ARTCL_NM, KWRD_CN, INTRP_RSLT_CN, MPNG_CD, SORT_SEQ, RMRK_CN, RGTR_ID, MDFR_ID)
SELECT 'AIMC0039'
     , '뉴스 카테고리'
     , C.COM_CD_NM
     , #{keyword.kwrdCn}
     , CONCAT('카테고리 = ', C.COM_CD_NM, '(CMUG06)')
     , #{keyword.mpngCd}
     , #{keyword.sortSeq}
     , '관리자 등록 (SCR-ADM-050)'
     , #{actorId}
     , #{actorId}
  FROM COM_CD C
 WHERE C.COM_CD = #{keyword.mpngCd}
   AND C.COM_CD_PRNT_SN IS NOT NULL

mapper.update:
/* 분류 키워드 삭제 */
UPDATE KWRD_DICT
   SET DEL_YN = 'Y'
     , MDFR_ID = #{actorId}
 WHERE KWRD_DICT_SN = #{kwrdDictSn}
   AND DICT_USG_CD = 'AIMC0039'
   AND USE_YN = 'Y'
   AND DEL_YN = 'N'

mapper.insert:
/* 수집한 뉴스 등록 : 원문 경로가 같은 기사는 건너뜀 */
INSERT IGNORE INTO NEWS (NEWS_CLSF_CD, NEWS_SRC_CD, NEWS_TTL, NEWS_CN, SRC_PRESS_NM, ORGTXT_PATH, PBLCN_DT, THMB_URL_PATH)
VALUES (#{newsClsfCd}, #{newsSrcCd}, #{newsTtl}, #{newsCn}, #{srcPressNm}, #{orgtxtPath}, #{pblcnDt}, #{thmbUrlPath})
